// 预算压力下的压缩点：不按保留期与设备位置过滤，快照位置及之前的提交全部可删。
func (q *Queries) SyncCompactionLimit(ctx context.Context, arg SyncCompactionLimitParams) (int64, error) {
	row := q.db.QueryRow(ctx, syncCompactionLimit, arg.UserID, arg.ThroughSeq)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const syncCompactionPoint = `-- name: SyncCompactionPoint :one
SELECT coalesce(max(seq), 0)::bigint
FROM sync_commit
WHERE user_id = $1
  AND seq <= $2
  AND ($3::bigint <= 0 OR seq <= $3::bigint)
  AND received_at < $4
`

type SyncCompactionPointParams struct {
	UserID     string
	ThroughSeq int64
	FloorSeq   int64
	Cutoff     pgtype.Timestamptz
}

// 常规压缩的删除点：快照位置及之前、服务端收到时间早于保留期、且不越过活跃窗口内
// 设备最小位置（floor_seq）的提交里最大的序号；没有可删的提交时返回 0，调用方据此
// 不动保留下界（ADR-0043、ADR-0054）。floor_seq 不大于零表示窗口内没有设备，不设
// 位置上限。
func (q *Queries) SyncCompactionPoint(ctx context.Context, arg SyncCompactionPointParams) (int64, error) {
	row := q.db.QueryRow(ctx, syncCompactionPoint,
		arg.UserID,
		arg.ThroughSeq,
		arg.FloorSeq,
		arg.Cutoff,
	)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const syncDevices = `-- name: SyncDevices :many
SELECT device_id, alias, snapshot_capable, synced_seq, first_seen, last_seen
FROM sync_device
WHERE user_id = $1
ORDER BY last_seen DESC, device_id
LIMIT $2
`

type SyncDevicesParams struct {
	UserID   string
	RowLimit int32
}

type SyncDevicesRow struct {
	DeviceID        string
	Alias           string
	SnapshotCapable bool
	SyncedSeq       int64
	FirstSeen       pgtype.Timestamptz
	LastSeen        pgtype.Timestamptz
}

func (q *Queries) SyncDevices(ctx context.Context, arg SyncDevicesParams) ([]SyncDevicesRow, error) {
	rows, err := q.db.Query(ctx, syncDevices, arg.UserID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SyncDevicesRow{}
	for rows.Next() {
		var i SyncDevicesRow
		if err := rows.Scan(
			&i.DeviceID,
			&i.Alias,
			&i.SnapshotCapable,
			&i.SyncedSeq,
			&i.FirstSeen,
			&i.LastSeen,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const syncIncomingBytes = `-- name: SyncIncomingBytes :one
SELECT coalesce(sum(pg_column_size(contents.data)), 0)::bigint
FROM unnest($1::jsonb[]) AS contents(data)
`

func (q *Queries) SyncIncomingBytes(ctx context.Context, changes [][]byte) (int64, error) {
	row := q.db.QueryRow(ctx, syncIncomingBytes, changes)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

